expectedAnswer.referenceSolver:
# VOCAB is part of the starter code
VOCAB = {"<pad>": 0, "<unk>": 1, "<eos>": 2, "</w>": 3, "a": 4, "b": 5, "c": 6, "d": 7, "e": 8,
         "l": 9, "o": 10, "s": 11, "t": 12, "w": 13}

def encode(text):
    """Word-wise char encoding: chars + </w> per word, one <eos> at the end."""
    ids = []
    for word in text.split(" "):
        if word == "":
            raise ValueError("leeres Wort")
        for ch in word:
            if ch not in VOCAB:
                raise ValueError("unbekanntes Zeichen: " + ch)
            ids.append(VOCAB[ch])
        ids.append(VOCAB["</w>"])
    ids.append(VOCAB["<eos>"])
    return ids

def decode(ids):
    """Inverse of encode; everything after <eos> is ignored."""
    inv = {v: k for k, v in VOCAB.items()}
    words = []
    current = ""
    for i in ids:
        if i == VOCAB["<eos>"]:
            break
        if i not in inv:
            raise ValueError("unbekannte Token-ID")
        tok = inv[i]
        if tok == "</w>":
            words.append(current)
            current = ""
        elif tok in ("<pad>", "<unk>"):
            raise ValueError("Sondertoken im Datenstrom")
        else:
            current += tok
    if current:
        words.append(current)
    return " ".join(words)

