def bpe_encode(word, merges):
    """Apply the merge table in order: each merge hits all occurrences (left-to-right, non-overlapping)."""
    symbols = list(word) + ["</w>"]
    for pair in merges:
        a, b = pair
        out = []
        i = 0
        while i < len(symbols):
            if i + 1 < len(symbols) and symbols[i] == a and symbols[i + 1] == b:
                out.append(a + b)
                i += 2
            else:
                out.append(symbols[i])
                i += 1
        symbols = out
    return symbols

def learn_merges(corpus, num_merges):
    """BPE learning with pinned rules: most frequent pair, ties -> lexicographically
    smallest pair, stop early when no pair occurs more than once."""
    words = [list(word) + ["</w>"] for word in corpus]
    merges = []
    for _ in range(int(num_merges)):
        counts = {}
        for syms in words:
            for i in range(len(syms) - 1):
                pair = (syms[i], syms[i + 1])
                counts[pair] = counts.get(pair, 0) + 1
        if not counts:
            break
        max_count = max(counts.values())
        if max_count < 2:
            break
        best = min(pair for pair, count in counts.items() if count == max_count)
        merges.append(best)
        a, b = best
        merged_words = []
        for syms in words:
            out = []
            i = 0
            while i < len(syms):
                if i + 1 < len(syms) and syms[i] == a and syms[i + 1] == b:
                    out.append(a + b)
                    i += 2
                else:
                    out.append(syms[i])
                    i += 1
            merged_words.append(out)
        words = merged_words
    return merges

